\label{pro3.1}
	Assume that $U\subseteq\mathbb{R}^m$ is a nonempty set, and $F: U\to\mathbb{R}^m$ is an operator. Then,
	\begin{enumerate}
	\item[$\mathbf{(i)}$] $F$ is $\alpha$-symmetric smooth with $\alpha\in(0,1)$ and constants $L_0, L_1\geq0$, if and only if,	for all $y,y'\in U$,
	\begin{equation*}
		\|F(y)-F(y')\|\leq\|y-y'\|\left(K_0+K_1\|F(y')\|^\alpha
		+K_2\|y-y'\|^{\frac{\alpha}{1 - \alpha}}\right),
	\end{equation*}
	where ${K}_{0} = {L}_{0}\left( 2^{\frac{\alpha^2}{1 - \alpha}} + 1\right)$, ${K}_{1}=L_1{2}^{\frac{\alpha^2}{1 - \alpha}}$, and ${K}_2= {L}_1^{\frac{1}{1 - \alpha}}{2}^{\frac{\alpha^2}{1 - \alpha}}3^{\alpha}(1 - \alpha)^{\frac{\alpha}{1 - \alpha}}$.

	\item[$\mathbf{(ii)}$] $F$ is $\alpha$-symmetric smooth with $\alpha=1$ and constants $L_0, L_1\geq0$, if and only if,  for all $y,y'\in U$,
	\begin{equation*}
		\|F(y)-F(y')\|\leq\|y-y'\|\bigl(L_0+L_1\|F(y')\|\bigr)\exp\bigl(L_1\|y-y'\|\bigr).
	\end{equation*}
\end{enumerate}

\label{lem21}
	Let $U\subseteq\mathbb{R}^m$ be nonempty, closed, and convex. Then, for
	every $u\in U$ and $v\in\mathbb{R}^m$,
	\begin{equation}\label{2.1}
		\langle v-P_U(v),u-P_U(v)\rangle\le0,
	\end{equation}
	and
	\begin{equation}\label{2.2}
		\|u-P_U(v)\|^2\leq\|u-v\|^2-\|v-P_U(v)\|^2.
	\end{equation}
	Moreover, $P_U$ is nonexpansive:
	\begin{equation}\label{2.3}
		\|P_U(x)-P_U(y)\|\le\|x-y\|,
		\qquad x,y\in\mathbb{R}^m.
	\end{equation}

\label{lem23}
	Let $\{v_k\}$, $\{w_k\}$, $\{a_k\}$, and $\{b_k\}$ be
	nonnegative scalar sequences satisfying
	\begin{equation*}
		v_{k+1}\le(1+a_k)v_k-w_k+b_k,
		\qquad k\ge0.
	\end{equation*}
	If
	\begin{equation*}
		\sum_{k=0}^{\infty}a_k<\infty,
		\qquad
		\sum_{k=0}^{\infty}b_k<\infty,
	\end{equation*}
	then $\{v_k\}$ converges to some $v\ge0$, and
	\begin{equation*}
		\sum_{k=0}^{\infty}w_k<\infty.
	\end{equation*}

\label{lem:rs}
	Let $\{v_k\}$, $\{z_k\}$, $\{a_k\}$, and $\{b_k\}$ be
	nonnegative random variables adapted to a filtration
	$\{\mathcal F_k\}$. Suppose that
	\begin{equation*}
		\mathbb E[v_{k+1}\mid\mathcal F_k]
		\le(1+a_k)v_k-z_k+b_k,
		\qquad k\ge0,
	\end{equation*}
	almost surely, and that
	\begin{equation*}
		\sum_{k=0}^{\infty}a_k<\infty,
		\qquad
		\sum_{k=0}^{\infty}b_k<\infty
		\qquad\text{almost surely}.
	\end{equation*}
	Then $v_k$ converges almost surely to a finite nonnegative random variable,
	and
	\begin{equation*}
		\sum_{k=0}^{\infty}z_k<\infty
		\qquad\text{almost surely}.
	\end{equation*}

\label{lem25}
	Let $\{v_k\}$ and $\{a_k\}$ be nonnegative scalar sequences, and let
	$q>0$. Suppose that
	\begin{equation*}
		v_{k+1}\le v_k-a_kv_k^{1+q},
		\qquad k\ge0.
	\end{equation*}
	Then
	\begin{equation*}
		v_k\le\frac{v_0}{\left(1+qv_0^q\sum_{i=0}^{k-1}a_i\right)^{1/q}}.
	\end{equation*}
	In particular, if $a_k=a>0$ for all $k$, then
	\begin{equation*}
		v_k\le\frac{v_0}{\left(1+aqv_0^q k\right)^{1/q}}.
	\end{equation*}

\label{lem31}
	Let $\{\lambda_k\}$ be the stepsize sequence generated by Algorithm~\ref{alg3}. Then the following statements hold.
	\begin{enumerate}
		\item[$\mathbf{(i)}$] The sequence is uniformly bounded above:
		\begin{equation}\label{eq:lambda-upper}
			0<\lambda_k\le \bar\lambda
			:=\lambda_0\exp\!\left(\sum_{j=0}^{\infty}\eta_j\right),
			\qquad k\ge0.
		\end{equation}

		\item[$\mathbf{(ii)}$] The stepsize sequence converges:
		\begin{equation}\label{eq:lambda-limit}
			\lambda_k\to\lambda_\infty
			\qquad\text{for some }\lambda_\infty\ge0.
		\end{equation}

		\item[$\mathbf{(iii)}$] The positive and negative variations are summable:
		\begin{equation}\label{eq:lambda-variation}
			\sum_{k=0}^{\infty}(\lambda_{k+1}-\lambda_k)_+<\infty,
			\qquad
			\sum_{k=0}^{\infty}(\lambda_{k+1}-\lambda_k)_-<\infty,
		\end{equation}
		where
		\begin{equation*}
			(a)_+:=\max\{a,0\},
			\qquad
			(a)_-:=\max\{-a,0\}.
		\end{equation*}
		Consequently,
		\begin{equation}\label{eq:lambda-total-variation}
			\sum_{k=0}^{\infty}|\lambda_{k+1}-\lambda_k|<\infty.
		\end{equation}
	\end{enumerate}

By the first term in the stepsize rule \eqref{eq:pf-aeg-stepsize}, $\lambda_{k+1}\le(1+\eta_k)\lambda_k$. 	Iterating this inequality and using $\log(1+x)\le x$ for $x\ge0$, we obtain
	\begin{align*}
		\lambda_{k+1}
		&\le \lambda_0\prod_{j=0}^{k}(1+\eta_j)
		\le \lambda_0\exp\!\left(\sum_{j=0}^{k}\eta_j\right)
		\le \lambda_0\exp\!\left(\sum_{j=0}^{\infty}\eta_j\right)
		=\bar\lambda,
	\end{align*}
	which proves $\mathbf{(i)}$.

	We next prove $\mathbf{(iii)}$. The stepsize rule \eqref{eq:pf-aeg-stepsize} gives
	$\lambda_{k+1}-\lambda_k\le\eta_k\lambda_k\le\bar\lambda\eta_k$. Hence
	\begin{equation*}
		(\lambda_{k+1}-\lambda_k)_+
		\le \bar\lambda\eta_k.
	\end{equation*}
	Since $\sum_{k=0}^{\infty}\eta_k<\infty$, it follows that
	\begin{equation*}
		\sum_{k=0}^{\infty}(\lambda_{k+1}-\lambda_k)_+<\infty.
	\end{equation*}
	Moreover, for every $N\ge0$,
	\begin{align*}
		\lambda_{N+1}-\lambda_0
		&=\sum_{k=0}^{N}(\lambda_{k+1}-\lambda_k)_+
		-\sum_{k=0}^{N}(\lambda_{k+1}-\lambda_k)_-.
	\end{align*}
	Since $\lambda_{N+1}\ge0$,
	\begin{equation*}
		\sum_{k=0}^{N}(\lambda_{k+1}-\lambda_k)_-
		\le
		\lambda_0+\sum_{k=0}^{N}(\lambda_{k+1}-\lambda_k)_+.
	\end{equation*}
	Letting $N\to\infty$ proves the second assertion in \eqref{eq:lambda-variation}, and therefore \eqref{eq:lambda-total-variation} follows.

	Finally, \eqref{eq:lambda-total-variation} implies that $\{\lambda_k\}$ is a Cauchy sequence in $\mathbb{R}$. Thus it converges to a finite limit $\lambda_\infty\ge0$, proving $\mathbf{(ii)}$.

\label{lem32}
	Let $\{t_k\}$ and $\{z_k\}$ be generated by Algorithm~\ref{alg3}. Then, for every $y\in U$ and every $k\ge0$,
	\begin{equation}\label{4.1}
		\|z_{k+1}-y\|^2\le
		\|z_k-y\|^2-\|z_k-t_k\|^2
		-2\lambda_k\langle F(t_k),t_k-y\rangle
		+\lambda_k^2\|F(z_k)-F(t_k)\|^2.
	\end{equation}

Since
	\begin{equation*}
		z_{k+1}=P_U\bigl(z_k-\lambda_kF(t_k)\bigr),
	\end{equation*}
	the projection inequality \eqref{2.2} gives, for every $y\in U$,
	\begin{align}
		\|z_{k+1}-y\|^2
		&\le\|z_k-\lambda_kF(t_k)-y\|^2
		-\|z_k-\lambda_kF(t_k)-z_{k+1}\|^2 \notag\\
		&=\|z_k-y\|^2-\|z_{k+1}-z_k\|^2
		+2\lambda_k\langle F(t_k),y-z_{k+1}\rangle.
		\label{4.3}
	\end{align}
	Using
	\begin{equation*}
		\|z_{k+1}-z_k\|^2=\|z_{k+1}-t_k\|^2
		+\|z_k-t_k\|^2-2\langle z_{k+1}-t_k,z_k-t_k\rangle,
	\end{equation*}
	we can rewrite \eqref{4.3} as
	\begin{align}
		\|z_{k+1}-y\|^2
		&\le\|z_k-y\|^2-\|z_{k+1}-t_k\|^2-\|z_k-t_k\|^2
		-2\lambda_k\langle F(t_k),t_k-y\rangle \notag\\
		&\quad
		+2\langle z_{k+1}-t_k,
		z_k-\lambda_kF(z_k)-t_k\rangle
		+2\lambda_k\langle F(z_k)-F(t_k),z_{k+1}-t_k\rangle.
		\label{4.5}
	\end{align}
	Because $t_k=P_U\bigl(z_k-\lambda_kF(z_k)\bigr)$,
	the projection optimality condition \eqref{2.1}, with $z_{k+1}\in U$, implies
	\begin{equation*}
		\langle z_{k+1}-t_k,z_k-\lambda_kF(z_k)-t_k\rangle\le0.
	\end{equation*}
	In addition, the Cauchy--Schwarz and Young inequalities yield
	\begin{equation*}
		2\lambda_k\langle F(z_k)-F(t_k),z_{k+1}-t_k\rangle
		\le
		\lambda_k^2\|F(z_k)-F(t_k)\|^2
		+\|z_{k+1}-t_k\|^2.
	\end{equation*}
	Substituting these two estimates into \eqref{4.5} gives \eqref{4.1}.

\label{th61}
	Suppose that Assumptions~\ref{ass1}--\ref{ass3} hold, and let
	$\{t_k\}$ and $\{z_k\}$ be generated by Algorithm~\ref{alg3}. Then:
	\begin{enumerate}
		\item[$\mathbf{(i)}$]
		For every $t^*\in U^*$ and every $k\ge1$,
		\begin{equation}\label{eq:descent}
			\|z_{k+1}-t^*\|^2\le\|z_k-t^*\|^2-\frac12\|z_k-t_k\|^2
			-2\mu\lambda_k\operatorname{dist}^p(t_k,U^*)
			+M(\lambda_k-\lambda_{k+1})_+,
		\end{equation}
		where
		\begin{equation*}
			M=
			\begin{cases}
				\displaystyle
				\left(
				\bar{\lambda}K_0
				+\bar{\lambda}^{\frac{2-\alpha}{2}}K_1
				+\bar{\lambda}^{\frac{2-\alpha}{2(1-\alpha)}}K_2
				\right)^2,
				& \alpha\in(0,1),\\[3mm]
				\displaystyle
				\left(
				\bar{\lambda}L_0+\sqrt{\bar{\lambda}}\,L_1
				\right)^2
				e^{2L_1\sqrt{\bar{\lambda}}},
				& \alpha=1.
			\end{cases}
		\end{equation*}

		\item[$\mathbf{(ii)}$]
		There exists $C>0$ such that $\|F(z_k)\|\le C$ for all $k\ge0$.
		Moreover,
		\begin{equation}\label{eq:lambda-lower}
			\lambda_k\ge\underline{\lambda}>0,
			\qquad k\ge0,
		\end{equation}
		where
		\begin{equation*}
			\underline{\lambda}
			=
			\begin{cases}
				\displaystyle
				\min\left\{
				\lambda_0,\,
				\lambda_1,\,
				\frac{1}{
					2\bar{\lambda}
					\left(
					K_0+K_1C^\alpha
					+K_2\bar{\lambda}^{\frac{\alpha}{2(1-\alpha)}}
					\right)^2
				},\,
				\frac{1}{C^2}
				\right\},
				& \alpha\in(0,1),\\[4mm]
				\displaystyle
				\min\left\{
				\lambda_0,\,
				\lambda_1,\,
				\frac{1}{
					2\bar{\lambda}(L_0+L_1C)^2
					e^{2L_1\sqrt{\bar{\lambda}}}
				},\,
				\frac{1}{C^2}
				\right\},
				& \alpha=1.
			\end{cases}
		\end{equation*}

		\item[$\mathbf{(iii)}$]
		Both $\{z_k\}$ and $\{t_k\}$ converge to a common solution
		$\bar t\in U^*$.
	\end{enumerate}

\textbf{(i)}
	By \eqref{eq:operator-norm-control} and the nonexpansiveness of $P_U$, for every $k\ge1$,
	\begin{align}
		\|z_k-t_k\|
		&=\left\|P_U(z_k)-P_U\bigl(z_k-\lambda_kF(z_k)\bigr)\right\| \notag\\
		&\le
		\lambda_k\|F(z_k)\|=
		\sqrt{\lambda_k}
		\bigl(\lambda_k\|F(z_k)\|^2\bigr)^{1/2}
		\le	\sqrt{\bar{\lambda}}.
		\label{eq:zk-tk-bound}
	\end{align}
	Suppose first that $\alpha\in(0,1)$. Applying Proposition~\ref{pro3.1} with $y=t_k$ and $y'=z_k$ gives
	\begin{equation}\label{eq:operator-difference-alpha-pre}
		\|F(z_k)-F(t_k)\|\le\|z_k-t_k\|
		\left(K_0+K_1\|F(z_k)\|^\alpha
		+K_2\|z_k-t_k\|^{\frac{\alpha}{1-\alpha}}\right).
	\end{equation}
	Moreover, \eqref{eq:zk-tk-bound} implies
	\begin{equation}\label{eq:zk-tk-bound-1}
		\|z_k-t_k\|^{\frac{\alpha}{1-\alpha}}
		\le
		\bar{\lambda}^{\frac{\alpha}{2(1-\alpha)}}.
	\end{equation}
	Using \eqref{eq:operator-norm-control}, \eqref{eq:zk-tk-bound}, and \eqref{eq:zk-tk-bound-1}, we obtain
	\begin{align*}
		\sqrt{\lambda_k}\|F(z_k)-F(t_k)\|
		&\le
		\bar{\lambda}K_0
		+\sqrt{\bar{\lambda}}K_1
		\lambda_k^{\frac{1-\alpha}{2}}
		\bigl(\lambda_k\|F(z_k)\|^2\bigr)^{\alpha/2}
		+K_2\bar{\lambda}^{\frac{2-\alpha}{2(1-\alpha)}}\\
		&\le
		\bar{\lambda}K_0
		+\bar{\lambda}^{\frac{2-\alpha}{2}}K_1
		+\bar{\lambda}^{\frac{2-\alpha}{2(1-\alpha)}}K_2.
	\end{align*}
	Similarly, when $\alpha=1$, 
	\begin{align*}
		\sqrt{\lambda_k}\|F(z_k)-F(t_k)\|
		&\le
		\sqrt{\lambda_k}\|z_k-t_k\|
		\bigl(L_0+L_1\|F(z_k)\|\bigr)
		e^{L_1\|z_k-t_k\|}\\
		&\le
		\left(\bar{\lambda}L_0
		+\sqrt{\bar{\lambda}}L_1\right)
		e^{L_1\sqrt{\bar{\lambda}}}.
	\end{align*}
	Hence, in both cases,
	\begin{equation}\label{eq:operator-difference-bound}
		\lambda_k\|F(z_k)-F(t_k)\|^2
		\le M,
		\qquad k\ge1.
	\end{equation}
	Since
	\begin{equation*}
		\lambda_k^2\le\lambda_k\lambda_{k+1}
		+\lambda_k(\lambda_k-\lambda_{k+1})+,
	\end{equation*}
	Lemma~\ref{lem32}, \eqref{eq:local-difference-control}, and \eqref{eq:operator-difference-bound} imply that, for every $y\in U$,
	\begin{align*}
		\|z_{k+1}-y\|^2\le&
		\|z_k-y\|^2-\frac12\|z_k-t_k\|^2
		-2\lambda_k\langle F(t_k),t_k-y\rangle
		+M(\lambda_k-\lambda_{k+1})_+.
	\end{align*}
	Taking $y=t^*\in U^*$ and using $p$-quasi-sharpness proves \eqref{eq:descent}.

	\medskip
	\noindent\textbf{(ii)}
	Fix any $t^*\in U^*$. Summing \eqref{eq:descent} from $k=1$ to $n$ and dropping the nonpositive terms gives
	\begin{equation*}
		\|z_{n+1}-t^*\|^2\le\|z_1-t^*\|^2+
		M\sum_{k=1}^{n}(\lambda_k-\lambda_{k+1})+.
	\end{equation*}
	By Lemma~\ref{lem31}, the series on the right-hand side is convergent. Hence $\{z_k\}$ is bounded. Since $U$ is closed and $F$ is continuous, there exists $C>0$ such that
	\begin{equation}\label{eq:Fzk-bound}
		\|F(z_k)\|\le C,
		\qquad k\ge0.
	\end{equation}
	If $\alpha\in(0,1)$, then \eqref{eq:operator-difference-alpha-pre}, \eqref{eq:zk-tk-bound-1}, and \eqref{eq:Fzk-bound} give
	\begin{equation*}\label{eq:operator-difference-alpha}
		\|F(z_k)-F(t_k)\|\le\|z_k-t_k\|
		\left(K_0+K_1C^\alpha
		+K_2\bar{\lambda}^{\frac{\alpha}{2(1-\alpha)}}\right),
		\qquad k\ge1.
	\end{equation*}
	Similarly, if $\alpha=1$,
	\begin{equation*}\label{eq:operator-difference-one}
		\|F(z_k)-F(t_k)\|\le\|z_k-t_k\|
		(L_0+L_1C)e^{L_1\sqrt{\bar{\lambda}}},
		\qquad k\ge1.
	\end{equation*}
	Therefore, whenever $F(z_k)\ne F(t_k)$,
	\begin{equation*}
		\frac{\|z_k-t_k\|^2}
		{2\lambda_k\|F(z_k)-F(t_k)\|^2}
		\ge
		\begin{cases}
			\displaystyle
			\frac{1}{
				2\bar{\lambda}
				\left(
				K_0+K_1C^\alpha
				+K_2\bar{\lambda}^{\frac{\alpha}{2(1-\alpha)}}
				\right)^2},
			& \alpha\in(0,1),\\[4mm]
			\displaystyle
			\frac{1}{
				2\bar{\lambda}(L_0+L_1C)^2
				e^{2L_1\sqrt{\bar{\lambda}}}},
			& \alpha=1.
		\end{cases}
	\end{equation*}
	If $F(z_k)=F(t_k)$, the corresponding candidate is interpreted as $+\infty$.
	By the definition of $\underline{\lambda}$, 
	$\lambda_0\ge\underline{\lambda}$ and
	$\lambda_1\ge\underline{\lambda}$. Suppose that
	$\lambda_k\ge\underline{\lambda}$ for some $k\ge1$. The first
	term in \eqref{eq:pf-aeg-stepsize} satisfies
	$(1+\eta_k)\lambda_k\ge\underline{\lambda}$. The preceding estimates show that the second candidate in \eqref{eq:pf-aeg-stepsize} is also no smaller than $\underline{\lambda}$.  Finally, by \eqref{eq:Fzk-bound}, the third candidate satisfies
	$1/\|F(z_{k+1})\|^2\ge1/C^2\ge\underline{\lambda}$, with the
	convention $1/0=+\infty$. Hence
	$\lambda_{k+1}\ge\underline{\lambda}$. By induction,
	\eqref{eq:lambda-lower} holds for all $k\ge0$.


	\medskip
	\noindent\textbf{(iii)}
	It follows from \eqref{eq:local-difference-control} and
	Lemma~\ref{lem32} that, for every $y\in U$,
	\begin{equation}\label{6.9}

			\|z_{k+1}-y\|^2\le\|z_k-y\|^2
			-\left(1-\frac{\lambda_k}{2\lambda_{k+1}}\right)\|z_k-t_k\|^2
			-2\lambda_k\langle F(t_k),t_k-y\rangle.

	\end{equation}
By Lemma~\ref{lem31} and \eqref{eq:lambda-lower}, $\{\lambda_k\}$ converges to a positive limit. Hence $\frac{\lambda_k}{\lambda_{k+1}}\to1$.



	Therefore, there exists $k_0\ge1$ such that
	\begin{equation*}\label{eq:ratio-control}
		1-\frac{\lambda_k}{2\lambda_{k+1}}
		\ge\frac14,
		\qquad k\ge k_0.
	\end{equation*}
	Fix an arbitrary $t^*\in U^*$. Taking $y=t^*\in U^*$ in \eqref{6.9} and applying $p$-quasi-sharpness and \eqref{eq:lambda-lower} give
	\begin{equation}\label{6.30}

			\|z_{k+1}-t^*\|^2\le\|z_k-t^*\|^2
			-\frac14\|z_k-t_k\|^2
			-2\mu\underline{\lambda}
			\operatorname{dist}^p(t_k,U^*),
			\qquad k\ge k_0.

	\end{equation}
	Applying Lemma~\ref{lem23} to the tail sequence in \eqref{6.30} shows that $\{\|z_k-t^*\|^2\}$ converges and
	\begin{equation*}\label{eq:summability-tail}
		\sum_{k=k_0}^{\infty}\|z_k-t_k\|^2<\infty,
		\qquad
		\sum_{k=k_0}^{\infty}\operatorname{dist}^p(t_k,U^*)<\infty.
	\end{equation*}
	Since only finitely many indices precede $k_0$, we get
	\begin{equation*}\label{eq:summability-global}
		\sum_{k=0}^{\infty}\|z_k-t_k\|^2<\infty,
		\qquad
		\sum_{k=0}^{\infty}\operatorname{dist}^p(t_k,U^*)<\infty.
	\end{equation*}
	Consequently,
	\begin{equation}\label{6.31}
		\|z_k-t_k\|\to0,
		\qquad
		\operatorname{dist}(t_k,U^*)\to0.
	\end{equation}

	We next show that every accumulation point of
	$\{z_k\}$ belongs to $U^*$.
	By part $\mathbf{(ii)}$, the sequence $\{z_k\}$ is bounded.
	Hence it has an accumulation point in $\mathbb{R}^m$.
	Let $\{z_{k_i}\}$ be a convergent subsequence such that $z_{k_i}\to\bar t$. 
	Since $z_{k_i}\in U$ and $U$ is closed, we have
	$\bar t\in U$.
	Moreover, \eqref{6.31} gives $\|t_{k_i}-z_{k_i}\|\to0$, 
	and therefore $t_{k_i}\to\bar t$. 
	Since the distance function is continuous,
	\eqref{6.31} yields
	\begin{equation*}
		\operatorname{dist}(\bar t,U^*)=
		\lim_{i\to\infty}\operatorname{dist}(t_{k_i},U^*)=0.
	\end{equation*}
	Since $U^*$ is closed, $\bar t\in U^*$. Thus every accumulation point of $\{z_k\}$ belongs to $U^*$.

	Finally, \eqref{6.30} implies that the tail sequence $\{z_k\}_{k\ge k_0}$ 
	is Fej\'er monotone with respect to $U^*$.
	Applying Lemma~\ref{lem:Fejer} to this tail sequence, we conclude
	that there exists $\bar t\in U^*$ such that $z_k\to\bar t$. 
	Together with $\|z_k-t_k\|\to0$, this further gives $t_k\to\bar t$. 
	Hence both $\{z_k\}$ and $\{t_k\}$ converge to the same
	solution $\bar t\in U^*$.

\label{th33}
	Suppose that Assumptions~\ref{ass1}--\ref{ass3} hold, and let
	$\{t_k\}$ and $\{z_k\}$ be generated by Algorithm~\ref{alg3}. Then the
	following statements hold.

	\begin{enumerate}
		\item[$\mathbf{(i)}$]
		If $0<p\le2$, then there exists $c>0$ such that
		\begin{equation}\label{eq:global-linear-rate}
			\operatorname{dist}^2(z_k,U^*)\le c\rho^k,
			\qquad k\ge0,
		\end{equation}
		where
		\begin{equation}\label{eq:rho}
			\rho:=1-\min\left\{\frac18,\,
			\frac{\mu\underline{\lambda}}{B^{2-p}}\right\}\in(0,1),
		\end{equation}
		and $B>0$ is a constant satisfying
		$\operatorname{dist}(t_k,U^*)\le B$ for all $k\ge0$.

		\item[$\mathbf{(ii)}$]
		If $p>2$, then there exists $c_p>0$ such that
		\begin{equation}\label{eq:global-sublinear-rate}
			\operatorname{dist}^2(z_k,U^*)
			\le\frac{c_p}{(k+1)^{2/(p-2)}},
			\qquad k\ge0.
		\end{equation}
	\end{enumerate}

By Theorem~\ref{th61}(iii), there exists $\bar t\in U^*$ such that $t_k\to\bar t$. Hence $\operatorname{dist}(t_k,U^*)\to0$.



	Therefore, there exists $B>0$ such that
	\begin{equation}\label{eq:B-bound}
		\operatorname{dist}(t_k,U^*)\le B,
		\qquad k\ge0.
	\end{equation}
	Let $k_0\ge1$ be such that \eqref{6.30} holds for all $k\ge k_0$. For each such $k$, let $z_k^*$ be the projection of $z_k$ onto	$U^*$, i.e., 

	\begin{equation*}
		\|z_k-z_k^*\|
		=
		\operatorname{dist}(z_k,U^*).
	\end{equation*}
	Taking $t^*=z_k^*$ in \eqref{6.30} gives
	\begin{equation}\label{eq:rate-basic}
		\operatorname{dist}^2(z_{k+1},U^*)
		\le
		\operatorname{dist}^2(z_k,U^*)
		-\frac14\|z_k-t_k\|^2
		-2\mu\underline{\lambda}
		\operatorname{dist}^p(t_k,U^*),
		\qquad k\ge k_0.
	\end{equation}
	Moreover, the triangle inequality yields
	\begin{equation}\label{eq:distance-split}
		\operatorname{dist}(z_k,U^*)
		\le\|z_k-t_k\|+\operatorname{dist}(t_k,U^*).
	\end{equation}

	\medskip
	\noindent\textbf{(i)}
	Suppose $0<p\le2$. Squaring \eqref{eq:distance-split} and using
	\eqref{eq:B-bound}, we obtain
	\begin{align*}
		\operatorname{dist}^2(z_k,U^*)
		&\le2\|z_k-t_k\|^2
		+2\operatorname{dist}^2(t_k,U^*)
		\le2\|z_k-t_k\|^2+2B^{2-p}\operatorname{dist}^p(t_k,U^*).
	\end{align*}
	By the definition of $\rho$ in \eqref{eq:rho},
	\begin{equation*}
		2(1-\rho)\le\frac14,
		\qquad
		2(1-\rho)B^{2-p}\le2\mu\underline{\lambda}.
	\end{equation*}
	Hence
	\begin{equation*}
		(1-\rho)\operatorname{dist}^2(z_k,U^*)
		\le\frac14\|z_k-t_k\|^2
		+2\mu\underline{\lambda}
		\operatorname{dist}^p(t_k,U^*).
	\end{equation*}
	Combining this inequality with \eqref{eq:rate-basic} yields
	\begin{equation*}
		\operatorname{dist}^2(z_{k+1},U^*)
		\le\rho\,\operatorname{dist}^2(z_k,U^*),
		\qquad k\ge k_0,
	\end{equation*}
	which implies
	\begin{equation*}\label{eq:linear-tail-rate}
		\operatorname{dist}^2(z_k,U^*)
		\le\rho^{\,k-k_0}
		\operatorname{dist}^2(z_{k_0},U^*),
		\qquad k\ge k_0.
	\end{equation*}


	Then \eqref{eq:global-linear-rate} holds for every $k\ge0$ by setting 
	\begin{equation*}
		c:=\max_{0\le j\le k_0}\rho^{-j}\operatorname{dist}^2(z_j,U^*).
	\end{equation*}


	\medskip
	\noindent\textbf{(ii)}
	Suppose $p>2$. By \eqref{eq:distance-split}, the fact that ${\left(a + b\right)}^{p} \leq  {2}^{p - 1}\left(a^{p} + b^{p}\right)$, and
	$\|z_k-t_k\|\le\sqrt{\bar{\lambda}}$, we have
	\begin{align*}
		\operatorname{dist}^p(z_k,U^*)
		&\le\left(\|z_k-t_k\|+\operatorname{dist}(t_k,U^*)\right)^p\\
		&\le2^{p-1}\left(\|z_k-t_k\|^p+\operatorname{dist}^p(t_k,U^*)
		\right)\\
		&\le2^{p-1}\left(\bar{\lambda}^{\frac{p-2}{2}}
		\|z_k-t_k\|^2+\operatorname{dist}^p(t_k,U^*)\right).
	\end{align*}
	Thus
	\begin{align*}
		&2^{2-p}
		\min\left\{
			\mu\underline{\lambda},
			\frac{1}{8\bar{\lambda}^{(p-2)/2}}
			\right\}
		\operatorname{dist}^p(z_k,U^*)
		\le\frac14\|z_k-t_k\|^2
		+2\mu\underline{\lambda}
		\operatorname{dist}^p(t_k,U^*).
	\end{align*}
	Combining this estimate with \eqref{eq:rate-basic} gives
	\begin{equation}\label{eq:sublinear-tail-recursion}
		\operatorname{dist}^2(z_{k+1},U^*)
		\le\operatorname{dist}^2(z_k,U^*)
		-2^{2-p}\min\left\{
			\mu\underline{\lambda},,
			\frac{1}{8\bar{\lambda}^{(p-2)/2}}
			\right\}
		\operatorname{dist}^p(z_k,U^*),
		\qquad k\ge k_0.
	\end{equation}
	Applying Lemma~\ref{lem25} to \eqref{eq:sublinear-tail-recursion} with $q=(p-2)/2$ yields
	\begin{equation}\label{eq:sublinear-tail-rate}
		\operatorname{dist}^2(z_k,U^*)
		\le\frac{\operatorname{dist}^2(z_{k_0},U^*)}{
			\left[1+a_p(k-k_0)
			\operatorname{dist}^{p-2}(z_{k_0},U^*)
			\right]^{2/(p-2)}
		},
		\qquad k\ge k_0,
	\end{equation}
	where
	\begin{equation*}
		a_p=2^{1-p}(p-2)
		\min\left\{
			\mu\underline{\lambda},
			\frac{1}{8\bar{\lambda}^{(p-2)/2}}
			\right\}.
	\end{equation*}
	If $\operatorname{dist}(z_{k_0},U^*)=0$, then
	\eqref{eq:sublinear-tail-recursion} implies
	$\operatorname{dist}(z_k,U^*)=0$ for all $k\ge k_0$, and the
	result follows immediately. 
	Otherwise, \eqref{eq:sublinear-tail-rate} implies, for $k\ge k_0+1$,
	\begin{equation*}
		\operatorname{dist}^2(z_k,U^*)
		\le\frac{1}{[a_p(k-k_0)]^{2/(p-2)}}.
	\end{equation*}
	For $k\ge k_0+1$, $k-k_0\ge\frac{k+1}{k_0+2}$,
	and hence
	\begin{equation*}
		\operatorname{dist}^2(z_k,U^*)\le
		\left(\frac{k_0+2}{a_p}\right)^{2/(p-2)}
		\frac{1}{(k+1)^{2/(p-2)}}.
	\end{equation*}
	Thus \eqref{eq:global-sublinear-rate} holds for every $k\ge0$ with
	\begin{equation*}
		c_p=\max\left\{
			\max_{0\le j\le k_0}
			(j+1)^{2/(p-2)}
			\operatorname{dist}^2(z_j,U^*),
			\left(\frac{k_0+2}{a_p}\right)^{2/(p-2)}
			\right\}.
	\end{equation*}

\label{ass4}
	For every $i\in[N]:=\{1,\ldots,N\}$, the component operator
	$F_i:U\to\mathbb{R}^m$ is continuous and satisfies the
	$\alpha$-symmetric generalized-smoothness condition for a common
	$\alpha\in(0,1]$. In particular, there exist
	$L_{0,i},L_{1,i}\ge0$ such that
	\begin{equation}\label{eq:component-generalized-smoothness}
		\|F_i(u)-F_i(v)\|\le
		\left(L_{0,i}+L_{1,i}\max_{\theta\in[0,1]}
		\|F_i(\theta u+(1-\theta)v)\|^\alpha\right)\|u-v\|,
		\qquad u,v\in U.
	\end{equation}

\label{lem41}
	Let $\{\lambda_k\}$ be generated by Algorithm~\ref{alg4}. Then, almost
	surely,
	\begin{equation}\label{eq:vr-lambda-upper}
		0<\lambda_k\le
		\bar\lambda:=
		\lambda_0\exp\!\left(\sum_{j=0}^{\infty}\eta_j\right),
		\qquad k\ge0,
	\end{equation}
	the limit $\lambda_k\to\lambda_\infty\ge0$ exists, and
	\begin{equation}\label{eq:vr-lambda-variation}
		\sum_{k=0}^{\infty}|\lambda_{k+1}-\lambda_k|<\infty.
	\end{equation}
	Moreover,
	\begin{equation}\label{eq:vr-lambda-variation-expectation}
		\sum_{k=0}^{\infty}\mathbb E(\lambda_{k+1}-\lambda_k)_+<\infty,
		\qquad
		\sum_{k=0}^{\infty}\mathbb E(\lambda_k-\lambda_{k+1})_+<\infty.
	\end{equation}

\label{lem42}
	Suppose Assumptions~\ref{ass1}--\ref{ass4} hold. For every $t^*\in U^*$
	and every $k\ge1$,
	\begin{align}\label{eq:vr-one-step}

			\mathbb E_k\|t^{k+1}-t^*\|^2
			\le&
			\beta\|t^k-t^*\|^2+(1-\beta)\|s^k-t^*\|^2
			-2\mu\lambda_k\operatorname{dist}^p(t^{k+\frac12},U^*)\notag\\
			&-(1-\beta)\mathbb E_k\|t^{k+1}-t^{k+\frac12}\|^2
			-(1-2\beta)\|s^k-t^{k+\frac12}\|^2
			-\beta\|t^k-t^{k+\frac12}\|^2\notag\\
			&+\bar M\,\mathbb E_k(\lambda_k-\lambda_{k+1})_+.

	\end{align}
	where $R=\beta w+\sqrt{\bar\lambda}$ and
	\begin{equation}\label{eq:Mbar}
		\bar M=
		\begin{cases}
			\displaystyle
			\frac{2R^2}{\beta}
			\left[\sqrt{\bar\lambda}
			\left(K_0+K_2R^{\frac{\alpha}{1-\alpha}}\right)
			+\bar\lambda^{\frac{1-\alpha}{2}}K_1
			\right]^2,
			& \alpha\in(0,1),\\[4mm]
			\displaystyle
			\frac{2R^2}{\beta}
			\left[(\sqrt{\bar\lambda}L_0+L_1)e^{L_1R}\right]^2,
			& \alpha=1.
		\end{cases}
	\end{equation}

\label{lem:finite-threshold}
	Assume
	\begin{equation}\label{eq:w-condition}
		w>\frac{1+\beta}{1-\beta-\beta^2}\sqrt{\bar\lambda}.
	\end{equation}
	Then the safeguard event
	\begin{equation*}
		A_k:=\{\|t^{k+1}-s^k\|>w\}
	\end{equation*}
	occurs only finitely many times almost surely.

For every $k\ge1$, by \eqref{2.3},  \eqref{eq:aeg-vr-correction}  and \eqref{eq:aeg-vr-stepsize},  we have 
	\begin{align}
		\|t^{k+1}-s^{k}\|
		\leq & \|t^{k+1}-t^{k+\frac{1}{2}}\|
		+\|t^{k+\frac{1}{2}}-s^{k}\|\notag \\



		\leq & \|t^{k+\frac{1}{2}}-s^{k}\|
		+\lambda_k\|F_{\xi_k}(t^{k+\frac{1}{2}})-F_{\xi_k}(s^k)\|\notag \\




		\leq &(1+\beta)\|t^{k+\frac{1}{2}}-s^{k}\|
		+(\lambda_k-\lambda_{k+1})_+
		\|F_{\xi_k}(t^{k+\frac{1}{2}})-F_{\xi_k}(s^k)\|,
		\label{f1}
	\end{align}
	where the last inequality follows from the second inequality by adding and subtracting the term $\lambda_{k+1}\|F_{\xi_k}(t^{k+\frac{1}{2}})-F_{\xi_k}(s^k)\|$.	
	Using \eqref{eq:vr-component-bound}, we obtain
	\begin{align*}
		(\lambda_k-\lambda_{k+1})_+
		\|F_{\xi_k}(t^{k+\frac{1}{2}})-F_{\xi_k}(s^k)\|
		\le&\sqrt{(\lambda_k-\lambda_{k+1})_+}\sqrt{\lambda_k}
		\|F_{\xi_k}(t^{k+\frac{1}{2}})-F_{\xi_k}(s^k)\|\\
		\le&\sqrt{\frac{\beta\bar M}{2}}\sqrt{(\lambda_k-\lambda_{k+1})_+},
	\end{align*}
	which together with \eqref{eq:vr-prediction-gap} and \eqref{f1}  gives
	\begin{equation}\label{eq:threshold-bound}
		\|t^{k+1}-s^k\|\le(1+\beta)R+
		\sqrt{\frac{\beta\bar M}{2}}\,
		\sqrt{(\lambda_k-\lambda_{k+1})_+},
		\qquad k\ge1.
	\end{equation}
	Condition \eqref{eq:w-condition} is equivalent to $w>(1+\beta)R$. Hence, on $A_k$,
	\begin{equation*}
		(\lambda_k-\lambda_{k+1})_+>\frac{2[w-(1+\beta)R]^2}{\beta\bar M}>0
	\end{equation*}
	when $\bar M>0$. Therefore,
	\begin{equation}
		\mathbf 1_{A_k}\le\frac{\beta\bar M}{2[w-(1+\beta)R]^2}
		(\lambda_k-\lambda_{k+1})_+.
		\label{eq:Ak-lambda-bound}
	\end{equation}
	Lemma~\ref{lem41} implies
	\begin{equation*}
		\sum_{k=1}^{\infty}\mathbf 1_{A_k}<\infty
		\qquad\text{almost surely}.
	\end{equation*}
	If $\bar M=0$, then \eqref{eq:threshold-bound} and
	\eqref{eq:w-condition} imply directly that $A_k$ does not occur for
	any $k\ge1$. In either case, the possible event at the single initial
	index $k=0$ does not affect the conclusion.

$\mathbf{(i)}$ Conditioning on $\mathcal G_k$, both $t^{k+1}$ and $A_k$ are
	measurable. If $A_k$ occurs, then $s^{k+1}=t^{k+1}$. If $A_k^c$
	occurs, then $s^{k+1}=t^{k+1}$ with probability $P_1$ and
	$s^{k+1}=s^k$ with probability $1-P_1$. Hence, for $k\ge1$,
	\begin{align}
		\mathbb E_k^+\|s^{k+1}-t^*\|^2
		=&\mathbf 1_{A_k}\|t^{k+1}-t^*\|^2
		+\mathbf 1_{A_k^c}
		\left[P_1\|t^{k+1}-t^*\|^2
		+(1-P_1)\|s^k-t^*\|^2\right].
		\label{eq:snapshot-cond-exp}
	\end{align}
	Rearranging \eqref{eq:snapshot-cond-exp} gives
	\begin{align}
		\frac{1-\beta}{P_1}
		\mathbb E_k^+\|s^{k+1}-t^*\|^2
		={}&(1-\beta)\|t^{k+1}-t^*\|^2
		+(1-\beta)\left(\frac1{P_1}-1\right)\|s^k-t^*\|^2
		\notag\\
		&+(1-\beta)
		\left(\frac1{P_1}-1\right)\mathbf 1_{A_k}
		\left(\|t^{k+1}-t^*\|^2-\|s^k-t^*\|^2\right).
		\label{eq:loopless-snapshot-identity}
	\end{align}

	We next bound the last term in
	\eqref{eq:loopless-snapshot-identity}. By the difference-of-squares
	identity and Young's inequality,
	\begin{align}
		\|t^{k+1}-t^*\|^2-\|s^k-t^*\|^2
		={}&2\langle s^k-t^*,t^{k+1}-s^k\rangle
		+\|t^{k+1}-s^k\|^2
		\notag\\
		\le{}&\|s^k-t^*\|^2+2\|t^{k+1}-s^k\|^2.
		\label{eq:snapshot-distance-difference}
	\end{align}
	Moreover, \eqref{eq:threshold-bound} and
	$(\lambda_k-\lambda_{k+1})_+\le\lambda_k\le\bar\lambda$ imply
	\begin{equation}\label{eq:tk1-sk-uniform}
		\|t^{k+1}-s^k\|\le(1+\beta)R+
		\sqrt{\frac{\beta\bar M\bar\lambda}{2}}
		=:\widehat C,
		\qquad k\ge1.
	\end{equation}
	Since
	\begin{equation*}
		\|s^k-t^*\|^2\le\frac{P_1}{1-\beta}\Phi_k(t^*),
	\end{equation*}
	it follows from \eqref{eq:snapshot-distance-difference} and
	\eqref{eq:tk1-sk-uniform} that
	\begin{align}
		&(1-\beta)
		\left(\frac1{P_1}-1\right)
		\mathbf 1_{A_k}
		\left(\|t^{k+1}-t^*\|^2-\|s^k-t^*\|^2\right)
		\notag\\
		&\qquad\le
		(1-P_1)\mathbf 1_{A_k}\Phi_k(t^*)
		+2(1-\beta)
		\left(\frac1{P_1}-1\right)
		\widehat C^2\mathbf 1_{A_k}.
		\label{eq:snapshot-extra-bound}
	\end{align}

	By the definition of $\Phi_{k+1}(t^*)$,
	\eqref{eq:loopless-snapshot-identity}, and
	\eqref{eq:snapshot-extra-bound},
	\begin{align}
		\mathbb E_k^+\Phi_{k+1}(t^*)
		={}&\beta\|t^{k+1}-t^*\|^2
		+\frac{1-\beta}{P_1}
		\mathbb E_k^+\|s^{k+1}-t^*\|^2
		\notag\\
		\le{}&\|t^{k+1}-t^*\|^2
		+(1-\beta)\left(\frac1{P_1}-1\right)\|s^k-t^*\|^2
		\notag\\
		&+(1-P_1)\mathbf 1_{A_k}\Phi_k(t^*)
		+2(1-\beta)\left(\frac1{P_1}-1\right)
\widehat C^2	\mathbf 1_{A_k}.
		\label{eq:Phi-Gk-bound}
	\end{align}
	Taking conditional expectation with respect to $\mathcal F_k$ and using
	the tower property, together with the $\mathcal F_k$-measurability of
	$\Phi_k(t^*)$, yields
	\begin{align}
		\mathbb E_k\Phi_{k+1}(t^*)
		\le{}&\mathbb E_k\|t^{k+1}-t^*\|^2
		+(1-\beta)\left(\frac1{P_1}-1\right)\|s^k-t^*\|^2
		\notag\\
		&+(1-P_1)\mathbb E_k\mathbf 1_{A_k}\Phi_k(t^*)
		+2(1-\beta)\left(\frac1{P_1}-1\right)
		\widehat C^2\mathbb E_k\mathbf 1_{A_k},
		\label{eq:Phi-Fk-bound}
	\end{align}
	Applying Lemma~\ref{lem42} to the first term on the right-hand side of
	\eqref{eq:Phi-Fk-bound}, and using
	\begin{equation*}
		(1-\beta)+(1-\beta)\left(\frac1{P_1}-1\right)
		=\frac{1-\beta}{P_1},
	\end{equation*}
	we obtain
	\begin{align}
		\mathbb E_k\Phi_{k+1}(t^*)
		\le{}&
		\left[1+(1-P_1)\mathbb E_k\mathbf 1_{A_k}\right]\Phi_k(t^*)
		-2\mu\lambda_k
		\operatorname{dist}^p(t^{k+\frac12},U^*)
		\notag\\
		&-(1-\beta)\mathbb E_k\|t^{k+1}-t^{k+\frac12}\|^2
		-(1-2\beta)\|s^k-t^{k+\frac12}\|^2
		-\beta\|t^k-t^{k+\frac12}\|^2
		\notag\\
		&+\bar M\mathbb E_k(\lambda_k-\lambda_{k+1})_+
		+2(1-\beta)\left(\frac1{P_1}-1\right)
	\widehat C^2\mathbb E_k\mathbf 1_{A_k},
		\qquad k\ge1
		\label{eq:vr-global-quasi-fejer},
	\end{align}

	It remains to verify the summability of the error terms in
	\eqref{eq:vr-global-quasi-fejer}. By the proof of
	Lemma~\ref{lem:finite-threshold}, \eqref{eq:Ak-lambda-bound} holds.
		Taking conditional expectation in \eqref{eq:Ak-lambda-bound} gives
	\begin{equation}\label{eq:Ak-conditional-bound}
		\mathbb E_k\mathbf 1_{A_k}
		\le\frac{\beta\bar M}{2[w-(1+\beta)R]^2}
		\mathbb E_k(\lambda_k-\lambda_{k+1})_+.
	\end{equation}
By Tonelli's theorem, the tower property, and Lemma~\ref{lem41}, we get
	\begin{align}
		\mathbb E
		\left[\sum_{k=1}^{\infty}
		\mathbb E_k(\lambda_k-\lambda_{k+1})_+\right]
		&=\sum_{k=1}^{\infty}
		\mathbb E(\lambda_k-\lambda_{k+1})_+<\infty.
		\label{eq:conditional-lambda-sum}
	\end{align}
	Therefore,
	\begin{equation*}\label{eq:conditional-lambda-summable}
		\sum_{k=1}^{\infty}
		\mathbb E_k(\lambda_k-\lambda_{k+1})_+
		<\infty
		\qquad\text{almost surely}.
	\end{equation*}
	Together with \eqref{eq:Ak-conditional-bound}, this further gives
	\begin{equation*}\label{eq:Ak-conditional-summable}
		\sum_{k=1}^{\infty}
		\mathbb E_k\mathbf 1_{A_k}<\infty
		\qquad\text{almost surely}.
	\end{equation*}
	Hence both the multiplicative error and the additive error in
	\eqref{eq:vr-global-quasi-fejer} are summable almost surely.

	Since $\beta\in\left(0,\frac12\right)$,



	all the descent terms in \eqref{eq:vr-global-quasi-fejer} are
	nonnegative. Applying Lemma~\ref{lem:rs} to the tail sequence
	$\{\Phi_k(t^*)\}_{k\ge1}$, we conclude that
	\begin{equation*}\label{eq:Phi-converges}
		\Phi_k(t^*)
		\quad\text{converges almost surely}.
	\end{equation*}
	Moreover, 
	\begin{equation}\label{eq:vr-tail-summability}
		\sum_{k=1}^{\infty}
		\lambda_k\operatorname{dist}^p(t^{k+\frac12},U^*)<\infty,
		\qquad
		\sum_{k=1}^{\infty}\|s^k-t^{k+\frac12}\|^2<\infty,
		\qquad
		\sum_{k=1}^{\infty}\|t^k-t^{k+\frac12}\|^2<\infty
	\end{equation}
	almost surely.

	Finally, convergence of $\Phi_k(t^*)$ implies that
	$\{\Phi_k(t^*)\}$ is bounded almost surely. Since
	$\beta>0$ and $(1-\beta)/P_1>0$, the definition of
	$\Phi_k(t^*)$ then implies that both $\{t^k\}$ and
	$\{s^k\}$ are bounded almost surely. This proves
	part~$\mathbf{(i)}$.


	\medskip
	\noindent\textbf{(ii)}
	We next establish a positive lower bound for the stepsizes. By
	part~$\mathbf{(i)}$, $\{s^k\}$ is bounded almost surely. Since
	$U$ is closed, $N<\infty$, and every $F_i$ is continuous, it follows
	that
	\begin{equation}\label{eq:H1-finite}
		H_1:=\sup_{k\ge0}
		\max_{i\in[N]}\|F_i(s^k)\|<\infty
		\qquad\text{almost surely}.
	\end{equation}

	Suppose first that $\alpha\in(0,1)$. By
	Assumption~\ref{ass4}, Proposition~\ref{pro3.1},
	\eqref{eq:H1-finite}, and \eqref{eq:vr-prediction-gap},
	\begin{align*}
		\|F_{\xi_k}(t^{k+\frac12})-F_{\xi_k}(s^k)\|
		&\le\|t^{k+\frac12}-s^k\|
		\left(K_0+K_1\|F_{\xi_k}(s^k)\|^\alpha+K_2
		\|t^{k+\frac12}-s^k\|^{\frac{\alpha}{1-\alpha}}
		\right)
		\notag\\
		&\le\|t^{k+\frac12}-s^k\|
		\left(K_0+K_1H_1^\alpha+K_2R^{\frac{\alpha}{1-\alpha}}\right),
		\qquad k\ge1.
		\label{eq:vr-component-lower-alpha}
	\end{align*}
	Hence, whenever
	$F_{\xi_k}(t^{k+\frac12})\ne F_{\xi_k}(s^k)$,
	the second candidate in \eqref{eq:aeg-vr-stepsize} satisfies
	\begin{equation}\label{eq:vr-local-candidate-alpha}
		\frac{\beta\|t^{k+\frac12}-s^k\|}
		{\|F_{\xi_k}(t^{k+\frac12})-F_{\xi_k}(s^k)\|}
		\ge\frac{\beta}{K_0+K_1H_1^\alpha+K_2R^{\frac{\alpha}{1-\alpha}}}.
	\end{equation}
	If the denominator is zero, the corresponding candidate is interpreted as
	$+\infty$, so the same lower bound remains valid.

	If $\alpha=1$, Proposition~\ref{pro3.1},
	\eqref{eq:H1-finite}, and \eqref{eq:vr-prediction-gap} give
	\begin{align*}
		\|F_{\xi_k}(t^{k+\frac12})-F_{\xi_k}(s^k)\|
		&\le\|t^{k+\frac12}-s^k\|
		\bigl(L_0+L_1\|F_{\xi_k}(s^k)\|\bigr)
		\exp\left(L_1\|t^{k+\frac12}-s^k\|\right)
		\notag\\
		&\le\|t^{k+\frac12}-s^k\|(L_0+L_1H_1)e^{L_1R},
		\qquad k\ge1.
		\label{eq:vr-component-lower-one}
	\end{align*}
	Therefore, whenever the denominator is nonzero,
	\begin{equation}\label{eq:vr-local-candidate-one}
		\frac{\beta\|t^{k+\frac12}-s^k\|}
		{\|F_{\xi_k}(t^{k+\frac12})-F_{\xi_k}(s^k)\|}
		\ge\frac{\beta}{(L_0+L_1H_1)e^{L_1R}}.
	\end{equation}


	By \eqref{eq:H1-finite},
	\begin{equation*}
		\underline{\lambda}>0
		\qquad\text{almost surely}.
	\end{equation*}
	Moreover, $\lambda_0\ge\underline{\lambda}$ and $\lambda_1\ge\underline{\lambda}$.	Suppose that
	$\lambda_k\ge\underline{\lambda}$ for some $k\ge1$.
	Then the first candidate in \eqref{eq:aeg-vr-stepsize} satisfies $(1+\eta_k)\lambda_k\ge\lambda_k\ge\underline{\lambda}$.
	By \eqref{eq:vr-local-candidate-alpha} or
	\eqref{eq:vr-local-candidate-one}, the second candidate is also no smaller
	than $\underline{\lambda}$. Finally,
	\begin{equation*}
		\frac{1}{\max_{i\in[N]}\|F_i(s^{k+1})\|^2}
		\ge\frac1{H_1^2}
		\ge\underline{\lambda}.
	\end{equation*}
	Thus every candidate in \eqref{eq:aeg-vr-stepsize} is bounded below by
	$\underline{\lambda}$, and hence $\lambda_{k+1}\ge\underline{\lambda}$.



	By induction, \eqref{eq:vr-lambda-lower} holds almost surely. This proves part~$\mathbf{(ii)}$.


	\medskip
	\noindent\textbf{(iii)}
	We finally prove the convergence of the iterates. By
	\eqref{eq:vr-tail-summability} and
	\eqref{eq:vr-lambda-lower},
	\begin{equation*}
		\sum_{k=1}^{\infty}
		\operatorname{dist}^p(t^{k+\frac12},U^*)
		\le\frac1{\underline{\lambda}}
		\sum_{k=1}^{\infty}
		\lambda_k\operatorname{dist}^p(t^{k+\frac12},U^*)
		<\infty
	\end{equation*}
	almost surely. Hence
	\begin{equation}\label{eq:vr-residual-limits}
		\operatorname{dist}(t^{k+\frac12},U^*)\to0,
		\qquad
		\|s^k-t^{k+\frac12}\|\to0,
		\qquad
		\|t^k-t^{k+\frac12}\|\to0
	\end{equation}
	almost surely, where the last two limits follow directly from
	\eqref{eq:vr-tail-summability}. Consequently,
	\begin{equation}\label{eq:tk-sk-zero}
		\|t^k-s^k\|\le\|t^k-t^{k+\frac12}\|
		+\|t^{k+\frac12}-s^k\|\to0
		\qquad\text{almost surely}.
	\end{equation}

	We next show that every accumulation point of $\{t^k\}$ belongs to
	$U^*$. Fix a sample path on which the preceding properties hold.
	By part~$\mathbf{(i)}$, $\{t^k\}$ is bounded. Let
	$\{t^{k_j}\}$ be a convergent subsequence such that $t^{k_j}\to u$. 
	By \eqref{eq:vr-residual-limits}, $\|t^{k_j+\frac12}-t^{k_j}\|\to0$, and hence $t^{k_j+\frac12}\to u$.	Since the distance function is continuous,
	\eqref{eq:vr-residual-limits} yields
	\begin{equation*}
		\operatorname{dist}(u,U^*)
		=\lim_{j\to\infty}
		\operatorname{dist}(t^{k_j+\frac12},U^*)=0.
	\end{equation*}
	Since $U^*$ is closed, $u\in U^*$. Thus every accumulation point of
	$\{t^k\}$ belongs to $U^*$.

	It remains to show that the accumulation point is unique. Since
	$U^*\subseteq\mathbb R^m$ is separable, let
	$\{u_j^*\}_{j\ge1}$ be a countable dense subset of  $U^*$.
	By part~$\mathbf{(i)}$, for every $j\ge1$,
	$\Phi_k(u_j^*)$ converges almost surely. Hence there exists an event of
	probability one on which
	\begin{equation*}\label{eq:Phi-dense-convergence}
		\Phi_k(u_j^*)
		\quad\text{converges for every }j\ge1.
	\end{equation*}
	Fix a sample path in this event, and let $u',u''\in U^*$ be two
	accumulation points of $\{t^k\}$. Then there exist subsequences such that
	\begin{equation*}
		t^{k_\ell}\to u',
		\qquad
		t^{m_\ell}\to u''.
	\end{equation*}
	By \eqref{eq:tk-sk-zero}, we have
	\begin{equation*}
		s^{k_\ell}\to u',
		\qquad
		s^{m_\ell}\to u''.
	\end{equation*}
	For every $j\ge1$, the convergence of
	$\Phi_k(u_j^*)$ implies that its limits along these two subsequences
	coincide. Therefore,
	\begin{equation}\label{eq:cluster-equality}
		\left(\beta+\frac{1-\beta}{P_1}\right)\|u'-u_j^*\|^2
		=\left(\beta+\frac{1-\beta}{P_1}\right)\|u''-u_j^*\|^2,
		\qquad j\ge1.
	\end{equation}
	By density, there exists a subsequence
	$\{u_{j_\ell}^*\}$ such that $u_{j_\ell}^*\to u'$. Passing to the limit in \eqref{eq:cluster-equality} along this subsequence
	gives
	\begin{equation*}
		\left(\beta+\frac{1-\beta}{P_1}\right)\|u''-u'\|^2=0.
	\end{equation*}
	Since $\beta+\frac{1-\beta}{P_1}>0$, we obtain $u''=u'$. Thus $\{t^k\}$ has a unique accumulation point.	Since it is bounded, there exists $\bar t\in U^*$ such that
	\begin{equation*}
		t^k\to\bar t
		\qquad\text{almost surely}.
	\end{equation*}
	Finally, \eqref{eq:tk-sk-zero} implies
	\begin{equation*}
		s^k\to\bar t
		\qquad\text{almost surely}.
	\end{equation*}
	This proves \eqref{eq:vr-as-convergence} and part~$\mathbf{(iii)}$.

\label{lem:vr-eventual-stability}
	Under the assumptions of Theorem~\ref{th41}, there exists an almost surely
	finite random index $K$ such that
	\begin{equation}\label{eq:vr-eventual-stability}
		\|t^{k+1}-s^k\|\le w,
		\qquad
		1-\beta-\beta\frac{\lambda_k^2}{\lambda_{k+1}^2}
		\ge\frac{1-2\beta}{2},
		\qquad k\ge K,
	\end{equation}
	almost surely. Moreover,
	\begin{equation}\label{eq:vr-prediction-distance-bound}
		\sup_{k\ge0}\operatorname{dist}(t^{k+\frac12},U^*)<\infty
		\qquad\text{almost surely}.
	\end{equation}

By Lemma~\ref{lem:finite-threshold}, the event $A_k$ occurs only finitely many times almost surely. Hence there exists an almost surely finite random index $K_1$ such that
	\begin{equation*}\label{eq:eventual-snapshot-gap}
		\|t^{k+1}-s^k\|\le w,
		\qquad k\ge K_1,
	\end{equation*}
	almost surely. By Lemma~\ref{lem41} and Theorem~\ref{th41}(ii), the stepsize sequence converges almost surely: $\lambda_k\to\lambda_\infty\ge	\underline{\lambda}>0$.	It follows that $\frac{\lambda_k}{\lambda_{k+1}}\to1$ almost surely. Consequently,
	\begin{equation*}
		1-\beta-\beta\frac{\lambda_k^2}{\lambda_{k+1}^2}
		\to1-2\beta
		\qquad\text{almost surely}.
	\end{equation*}
	Since $\beta\in(0,\frac12)$, we have $1-2\beta>0$. Thus there exists
	an almost surely finite random index $K_2$ such that
	\begin{equation*}\label{eq:eventual-ratio-bound}
		1-\beta-\beta\frac{\lambda_k^2}{\lambda_{k+1}^2}
		\ge\frac{1-2\beta}{2},
		\qquad k\ge K_2,
	\end{equation*}
	almost surely. Taking $K=\max\{K_1,K_2\}$ gives \eqref{eq:vr-eventual-stability}.

	It remains to prove \eqref{eq:vr-prediction-distance-bound}.
	By Theorem~\ref{th41}(iii), there exists
	$\bar t\in U^*$ such that $s^k\to\bar t$ almost surely.	Hence
	\begin{equation*}
		\sup_{k\ge0}\|s^k-\bar t\|<\infty
		\qquad\text{almost surely}.
	\end{equation*}
	For every $k\ge1$, \eqref{eq:vr-prediction-gap} gives
	\begin{align*}
		\operatorname{dist}(t^{k+\frac12},U^*)
		&\le\|t^{k+\frac12}-\bar t\|
		\le\|t^{k+\frac12}-s^k\|+\|s^k-\bar t\|
		\le R+\|s^k-\bar t\|.
	\end{align*}
	Therefore,
	\begin{equation*}
		\sup_{k\ge1}\operatorname{dist}(t^{k+\frac12},U^*)<\infty
		\qquad\text{almost surely}.
	\end{equation*}
	Since $t^{1/2}$ is finite, \eqref{eq:vr-prediction-distance-bound}
	follows.

\label{th43}
	Suppose the assumptions of Theorem~\ref{th41} and
	\eqref{eq:vr-rate-uniformity} hold.
	\begin{enumerate}
		\item[$\mathbf{(i)}$]
		If $0<p\le2$, and \eqref{eq:vr-uniform-B} additionally holds when
		$0<p<2$, then there exist $c>0$ such that
		\begin{equation}\label{eq:vr-linear-rate}
			\mathbb E\left[\inf_{u^*\in U^*}\Phi_k(u^*)\right]
			\le c\rho^k,
			\qquad k\ge0,
		\end{equation}
		where
		\begin{equation}\label{eq:vr-rho}
			\rho:=1-
			\min\left\{\frac12,\,
			\frac{(1-2\beta)P_1}{4(1-\beta)},\,
			\frac{\mu\lambda_{\min}}{\left(\beta+\frac{1-\beta}{P_1}\right)B^{2-p}}
			\right\}\in(0,1).
		\end{equation}

		\item[$\mathbf{(ii)}$]
		If $p>2$, then there exists $c_p>0$ such that
		\begin{equation}\label{eq:vr-sublinear-rate}
			\mathbb E\left[\inf_{u^*\in U^*}\Phi_k(u^*)\right]
			\le\frac{c_p}{(k+1)^{2/(p-2)}},
			\qquad k\ge0.
		\end{equation}
	\end{enumerate}

By \eqref{eq:vr-rate-uniformity},
	Theorem~\ref{th41}(ii), and
	Lemma~\ref{lem:vr-eventual-stability}, for every
	$k\ge k_{\rm r}$, almost surely,
	\begin{equation}\label{eq:vr-rate-tail-bounds}
		\lambda_k\ge\lambda_{\min},
		\qquad
		\|t^{k+1}-s^k\|\le w,
		\qquad
		1-\beta-\beta\frac{\lambda_k^2}{\lambda_{k+1}^2}
		\ge\frac{1-2\beta}{2}.
	\end{equation}
	Fix $k\ge k_{\rm r}$. The second inequality in
	\eqref{eq:vr-rate-tail-bounds} implies that the snapshot is updated
	according to the Bernoulli rule. Hence, for every $u^*\in U^*$,
	\begin{equation}\label{eq:vr-rate-snapshot}
		\frac{1-\beta}{P_1}
		\mathbb E_k^+\|s^{k+1}-u^*\|^2
		=(1-\beta)\|t^{k+1}-u^*\|^2
		+(1-\beta)\left(\frac1{P_1}-1\right)\|s^k-u^*\|^2.
	\end{equation}
	By the second candidate in \eqref{eq:aeg-vr-stepsize},
	\begin{equation}\label{eq:vr-rate-local-control}
		\frac{\lambda_k^2}{\beta}
		\|F_{\xi_k}(t^{k+\frac12})-F_{\xi_k}(s^k)\|^2
		\le\beta\frac{\lambda_k^2}{\lambda_{k+1}^2}
		\|t^{k+\frac12}-s^k\|^2.
	\end{equation}
	If the operator difference vanishes, this inequality holds trivially.
	Substituting \eqref{eq:vr-rate-local-control} into
	\eqref{eq:vr-prelocal} gives
	\begin{align}
		\|t^{k+1}-u^*\|^2
		\le{}&
		\beta\|t^k-u^*\|^2
		+(1-\beta)\|s^k-u^*\|^2
		-2\lambda_k
		\langle t^{k+\frac12}-u^*,\widehat F_k\rangle
		\notag\\
		&-(1-\beta)\|t^{k+1}-t^{k+\frac12}\|^2
		-\left(1-\beta-\beta\frac{\lambda_k^2}{\lambda_{k+1}^2}\right)
		\|s^k-t^{k+\frac12}\|^2
		\notag\\
		&-\beta\|t^k-t^{k+\frac12}\|^2.
		\label{eq:vr-rate-pre}
	\end{align}
	Using \eqref{eq:vr-rate-tail-bounds} in
	\eqref{eq:vr-rate-pre} and dropping the nonpositive term involving
	$\|t^{k+1}-t^{k+\frac12}\|^2$, we obtain
	\begin{align*}
		\|t^{k+1}-u^*\|^2
		\le{}&
		\beta\|t^k-u^*\|^2
		+(1-\beta)\|s^k-u^*\|^2
		-2\lambda_k
		\langle t^{k+\frac12}-u^*,\widehat F_k\rangle
		\notag\\
		&-
		\frac{1-2\beta}{2}
		\|s^k-t^{k+\frac12}\|^2
		-\beta\|t^k-t^{k+\frac12}\|^2.

	\end{align*}
	Taking conditional expectation with respect to $\mathcal F_k$, using
	\eqref{eq:svrg-unbiased}, $p$-quasi-sharpness, and
	$\lambda_k\ge\lambda_{\min}$, gives
	\begin{align}
		\mathbb E_k\|t^{k+1}-u^*\|^2
		\le{}&
		\beta\|t^k-u^*\|^2
		+(1-\beta)\|s^k-u^*\|^2
	-2\mu\lambda_{\min}
		\operatorname{dist}^p(t^{k+\frac12},U^*)
		\notag\\
		&-\frac{1-2\beta}{2}
		\|s^k-t^{k+\frac12}\|^2
		-\beta\|t^k-t^{k+\frac12}\|^2.
		\label{eq:vr-rate-t}
	\end{align}
	Taking conditional expectation with respect to $\mathcal F_k$ in
	\eqref{eq:vr-rate-snapshot} and using the tower property, we have
	\begin{align*}
		&\mathbb E_k
		\left[\beta\|t^{k+1}-u^*\|^2
		+\frac{1-\beta}{P_1}
		\|s^{k+1}-u^*\|^2\right]
		=\mathbb E_k\|t^{k+1}-u^*\|^2
		+(1-\beta)\left(\frac1{P_1}-1\right)
		\|s^k-u^*\|^2.
	\end{align*}
	Combining this identity with \eqref{eq:vr-rate-t} yields
	\begin{align*}
		\mathbb E_k[\Phi_{k+1}(u^*)]
		\le&
		\Phi_k(u^*)
		-2\mu\lambda_{\min}
		\operatorname{dist}^p(t^{k+\frac12},U^*)
		-\frac{1-2\beta}{2}
		\|s^k-t^{k+\frac12}\|^2
		-\beta\|t^k-t^{k+\frac12}\|^2.

	\end{align*}
	Since the preceding inequality holds for every $u^*\in U^*$, and
	\begin{equation*}
		\mathbb E_k\left[
		\inf_{u^*\in U^*}\Phi_{k+1}(u^*)\right]
		\le\inf_{u^*\in U^*}
		\mathbb E_k[\Phi_{k+1}(u^*)],
	\end{equation*}
	we obtain
	\begin{align}
		\mathbb E_k
		\left[\inf_{u^*\in U^*}\Phi_{k+1}(u^*)\right]
		\le{}&
		\inf_{u^*\in U^*}\Phi_k(u^*)
		-2\mu\lambda_{\min}
		\operatorname{dist}^p(t^{k+\frac12},U^*)
		\notag\\
		&-\frac{1-2\beta}{2}
		\|s^k-t^{k+\frac12}\|^2
		-\beta\|t^k-t^{k+\frac12}\|^2,
		\qquad k\ge k_{\rm r}.
		\label{eq:vr-rate-descent}
	\end{align}

	\medskip
	\noindent\textbf{(i)}
	Suppose $0<p\le2$. For each $k\ge k_{\rm r}$, let
	$u_k^*\in U^*$ satisfy $\|t^{k+\frac12}-u_k^*\|=\operatorname{dist}(t^{k+\frac12},U^*)$. 	By the definition of $\Phi_k$ and	$\|a+b\|^2\le2\|a\|^2+2\|b\|^2$,
	\begin{align}
		\inf_{u^*\in U^*}\Phi_k(u^*)
		\le{}&
		2\beta\|t^k-t^{k+\frac12}\|^2
		+\frac{2(1-\beta)}{P_1}
		\|s^k-t^{k+\frac12}\|^2
		\notag\\
		&+2\left(\beta+\frac{1-\beta}{P_1}\right)
		\operatorname{dist}^2(t^{k+\frac12},U^*).
		\label{eq:vr-linear-distance-bound}
	\end{align}
	If $0<p<2$, \eqref{eq:vr-uniform-B} implies
	\begin{equation*}
		\operatorname{dist}^2(t^{k+\frac12},U^*)
		\le B^{2-p}
		\operatorname{dist}^p(t^{k+\frac12},U^*).
	\end{equation*}
	For $p=2$, the same relation holds with $B^{2-p}=1$. 
	Combining the definition of $\rho$ in \eqref{eq:vr-rho} and
	\eqref{eq:vr-linear-distance-bound} gives
	\begin{align*}
		(1-\rho)
		\inf_{u^*\in U^*}\Phi_k(u^*)
		\le{}&
		\beta\|t^k-t^{k+\frac12}\|^2
		+\frac{1-2\beta}{2}
		\|s^k-t^{k+\frac12}\|^2
		+2\mu\lambda_{\min}
		\operatorname{dist}^p(t^{k+\frac12},U^*),

	\end{align*}
	which together with
	\eqref{eq:vr-rate-descent} yields
	\begin{equation*}\label{eq:vr-linear-contraction}
		\mathbb E_k
		\left[\inf_{u^*\in U^*}\Phi_{k+1}(u^*)\right]
		\le\rho\inf_{u^*\in U^*}\Phi_k(u^*),
		\qquad k\ge k_{\rm r}.
	\end{equation*}
	Taking total expectations and iterating gives
	\begin{equation*}\label{eq:vr-linear-tail}
		\mathbb E
		\left[\inf_{u^*\in U^*}\Phi_k(u^*)\right]
		\le\rho^{k-k_{\rm r}}
		\mathbb E
		\left[\inf_{u^*\in U^*}\Phi_{k_{\rm r}}(u^*)\right],
		\qquad k\ge k_{\rm r}.
	\end{equation*}
	Hence \eqref{eq:vr-linear-rate} holds for every $k\ge0$ by taking
	\begin{equation*}
		c:=\max_{0\le j\le k_{\rm r}}
		\rho^{-j}
		\mathbb E
		\left[\inf_{u^*\in U^*}\Phi_j(u^*)\right].
	\end{equation*}


	\medskip
	\noindent\textbf{(ii)}
	Suppose $p>2$. 









	Using the same argument as in \eqref{eq:vr-prediction-gap}, we obtain
	\begin{align*}
		\|t^k-t^{k+\frac12}\|
		&=\left\|P_U(t^k)
		-P_U\!\left(\bar t^k-\lambda_kF(s^k)\right)\right\|\\
		&\le(1-\beta)\|t^k-s^k\|+\lambda_k\|F(s^k)\|\\
		&\le(1-\beta)w+\sqrt{\bar\lambda},
		\qquad k\ge1,
	\end{align*}
	which together with \eqref{eq:vr-prediction-gap} gives
	\begin{equation}\label{eq:vr-weighted-gap-bound}
		\beta\|t^k-t^{k+\frac12}\|^2
		+\frac{1-\beta}{P_1}
		\|s^k-t^{k+\frac12}\|^2
		\le	R_0^2,
		\qquad k\ge k_{\rm r},
	\end{equation}
	where
		\begin{equation*}
		R_0^2:=\beta
		\left[(1-\beta)w+\sqrt{\bar\lambda}\right]^2
		+\frac{1-\beta}{P_1}R^2.
	\end{equation*}
	Let $u_k^*\in U^*$ be a nearest point to
	$t^{k+\frac12}$. By the triangle inequality,
	\begin{align*}
		\Phi_k(u_k^*)^{1/2}
		\le{}&
		\left[\beta\|t^k-t^{k+\frac12}\|^2
		+\frac{1-\beta}{P_1}
		\|s^k-t^{k+\frac12}\|^2\right]^{1/2}+
		\left(\beta+\frac{1-\beta}{P_1}\right)^{1/2}
		\operatorname{dist}(t^{k+\frac12},U^*).
	\end{align*}
	Using $(a+b)^p\le2^{p-1}(a^p+b^p)$ and
	\eqref{eq:vr-weighted-gap-bound}, we obtain
	\begin{align*}
		\left(\inf_{u^*\in U^*}\Phi_k(u^*)\right)^{p/2}
		\le{}&
		2^{p-1}R_0^{p-2}
		\left[\beta\|t^k-t^{k+\frac12}\|^2
		+\frac{1-\beta}{P_1}\|s^k-t^{k+\frac12}\|^2\right]
		\notag\\
		&+
		2^{p-1}\left(\beta+\frac{1-\beta}{P_1}\right)^{p/2}
		\operatorname{dist}^p(t^{k+\frac12},U^*),

	\end{align*}
	which implies
	\begin{align*}
		a_p\left(\inf_{u^*\in U^*}\Phi_k(u^*)\right)^{p/2}
		\le{}&
		\beta\|t^k-t^{k+\frac12}\|^2
		+\frac{1-2\beta}{2}
		\|s^k-t^{k+\frac12}\|^2
		+2\mu\lambda_{\min}
		\operatorname{dist}^p(t^{k+\frac12},U^*),
		\label{eq:vr-sublinear-control}
	\end{align*}
	where 
	\begin{equation*}\label{eq:vr-ap}
		a_p:=
		\min\left\{
		2^{1-p}R_0^{2-p}
		\min\left\{1,\,
		\frac{(1-2\beta)P_1}{2(1-\beta)}\right\},
		\frac{2^{2-p}\mu\lambda_{\min}}{
			\left(\beta+\frac{1-\beta}{P_1}\right)^{p/2}}
		\right\}.
	\end{equation*}
	Combining this estimate with
	\eqref{eq:vr-rate-descent} gives
	\begin{equation}
		\mathbb E_k
		\left[\inf_{u^*\in U^*}\Phi_{k+1}(u^*)\right]
		\le\inf_{u^*\in U^*}\Phi_k(u^*)
		-a_p\left(\inf_{u^*\in U^*}\Phi_k(u^*)\right)^{p/2},
		\qquad k\ge k_{\rm r}.
		\label{eq:vr-sublinear-recursion}
	\end{equation}
	Taking total expectations in
	\eqref{eq:vr-sublinear-recursion} and applying Jensen's inequality,
	since $p/2>1$, yields
	\begin{equation*}\label{eq:vr-sublinear-expectation-recursion}
		\mathbb E
		\left[\inf_{u^*\in U^*}\Phi_{k+1}(u^*)\right]
		\le\mathbb E
		\left[\inf_{u^*\in U^*}\Phi_k(u^*)\right]-a_p\left(\mathbb E
		\left[\inf_{u^*\in U^*}\Phi_k(u^*)\right]\right)^{p/2},
		\qquad k\ge k_{\rm r}.
	\end{equation*}
	Applying Lemma~\ref{lem25} with $q=(p-2)/2$ gives
	\begin{equation}\label{eq:vr-sublinear-tail}
		\mathbb E\left[\inf_{u^*\in U^*}\Phi_{k}(u^*)\right]
		\le\frac{\mathbb E
			\left[\displaystyle\inf_{u^*\in U^*}\Phi_{k_{\rm r}}(u^*)\right]}
			{\left[1+\frac{p-2}{2}
			a_p\left(\mathbb E
			\left[\displaystyle
			\inf_{u^*\in U^*}\Phi_{k_{\rm r}}(u^*)
			\right]\right)^{(p-2)/2}
			(k-k_{\rm r})\right]^{2/(p-2)}},
		\qquad k\ge k_{\rm r}.
	\end{equation}
	If $\mathbb E\left[\displaystyle\inf_{u^*\in U^*}\Phi_{k_{\rm r}}(u^*)\right]=0$, the result follows immediately. Otherwise, for $k\ge k_{\rm r}+1$,
\begin{equation*}
	\mathbb E\left[\inf_{u^*\in U^*}\Phi_k(u^*)\right]
	\le\left[\frac{p-2}{2}a_p(k-k_{\rm r})\right]^{-2/(p-2)}.
\end{equation*}
Since $k-k_{\rm r}\ge\frac{k+1}{k_{\rm r}+2}$ for $k\ge k_{\rm r}+1$, we obtain
\begin{equation*}
	\mathbb E\left[\inf_{u^*\in U^*}\Phi_k(u^*)\right]
	\le\left[\frac{2(k_{\rm r}+2)}{(p-2)a_p}\right]^{2/(p-2)}
	\frac1{(k+1)^{2/(p-2)}}.
\end{equation*}
Thus \eqref{eq:vr-sublinear-rate} holds for every $k\ge0$ by choosing
\begin{equation*}
	c_p:=\max\left\{
	\max_{0\le j\le k_{\rm r}}(j+1)^{2/(p-2)}
	\mathbb E
	\left[\inf_{u^*\in U^*}\Phi_j(u^*)\right],
	\left[\frac{2(k_{\rm r}+2)}{(p-2)a_p}\right]^{2/(p-2)}
	\right\}.
\end{equation*}
